  const circle = (cx, cy, r, o = {}) => { const a0 = o.a0 ?? -2.2; return mk(WP(ellP(cx, cy, r, o.ry ?? r, a0, a0 + TAU + (o.lap ?? 0.25))), { wav: 320, ...o }); };
  const dot = (x, y, o = {}) => mk(WP([[x, y], [x + 1.5, y + 1.5]]), { jit: 0, ...o });
