    const g1 = ctx.createLinearGradient(0, -24, 0, 24); g1.addColorStop(0, '#dfe2e6'); g1.addColorStop(0.35, '#ffffff'); g1.addColorStop(1, '#8b9099');
    ctx.fillStyle = g1; ctx.beginPath(); ctx.moveTo(20, -11); ctx.lineTo(56, -24); ctx.lineTo(56, 24); ctx.lineTo(20, 11); ctx.closePath(); ctx.fill();
    const g2 = ctx.createLinearGradient(0, -26, 0, 26); g2.addColorStop(0, '#f2f3f5'); g2.addColorStop(0.3, '#ffffff'); g2.addColorStop(0.8, '#c9cdd3'); g2.addColorStop(1, '#9ca1a9');
