    const g3 = ctx.createLinearGradient(0, -28, 0, 28); g3.addColorStop(0, col); g3.addColorStop(0.35, 'rgba(255,255,255,0.35)'); g3.addColorStop(1, col);
    ctx.fillStyle = col; ctx.beginPath(); ctx.roundRect(330, -28, 100, 56, 14); ctx.fill(); ctx.fillStyle = g3; ctx.globalAlpha = 0.35; ctx.fill(); ctx.globalAlpha = 1;
