    g.lineCap = 'round'; for (let i = 0; i < 260; i++) { g.strokeStyle = `rgba(0,0,0,${r() * 0.22})`; g.lineWidth = r() * 1.4 + 0.4; const x = r() * 512, y = r() * 512, a = (r() - 0.5) * 0.5, l = 20 + r() * 70; g.beginPath(); g.moveTo(x, y); g.lineTo(x + Math.cos(a) * l, y + Math.sin(a) * l); g.stroke(); }
    XC.nt = nt;
    const bt = H.layer(1024, 1024), b = bt.getContext('2d'), r2 = H.rng(11);
    for (let i = 0; i < 900; i++) { b.fillStyle = `rgba(90,95,105,${r2() * 0.03})`; b.beginPath(); b.arc(r2() * 1024, r2() * 1024, r2() * 2.5 + 0.5, 0, TAU); b.fill(); }
    b.lineCap = 'round'; for (let i = 0; i < 70; i++) { const al = r2() * 0.028, lw = r2() * 12 + 4, x = r2() * 1024, y = r2() * 1024, a = (r2() - 0.5) * 0.4, l = 40 + r2() * 260; b.strokeStyle = `rgba(80,86,96,${al})`; b.lineWidth = lw; for (const ox of [-1024, 0, 1024]) for (const oy of [-1024, 0, 1024]) { b.beginPath(); b.moveTo(x + ox, y + oy); b.lineTo(x + ox + Math.cos(a) * l, y + oy + Math.sin(a) * l); b.stroke(); } }
