    k.play('ding', T(1, 'why'), { f: 'E6', gain: 0.22 });
    k.play('swish', T(2, 'sky'), { gain: 0.3 });
    k.play('sparkle', T(3, 'glass'), { n: 4, gain: 0.25 });
    k.play('pop', T(4, 'plants'), { f: 620, gain: 0.25 });
    k.play('sparkle', T(5, 'mirror'), { n: 5, gain: 0.28 });
    k.play('whoosh', T(8, 'flies'), { dur: 0.8, gain: 0.35 });
    k.play('thud', T(8, 'wall'), { f: 90, gain: 0.5 });
    k.play('error', T(10, 'learned'), { gain: 0.22 });
    k.play('stamp', T(12, 'billion'), { gain: 0.45 });
    k.play('thud', T(15, 'it'), { f: 100, gain: 0.35 });
